import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import '../../services/auth_service.dart';import '../../core/utils/validators.dart';import '../../core/routes/app_routes.dart';
class LoginScreen extends StatefulWidget {final AuthService auth;const LoginScreen({super.key,required this.auth});@override State<LoginScreen> createState()=>_LoginScreenState();}
class _LoginScreenState extends State<LoginScreen>{final form=GlobalKey<FormState>();final username=TextEditingController(),password=TextEditingController();bool loading=false;String? error;@override void dispose(){username.dispose();password.dispose();super.dispose();}
 Future<void> submit()async{if(!form.currentState!.validate())return;setState((){loading=true;error=null;});try{await widget.auth.login(username.text.trim(),password.text);if(mounted)context.go(AppRoutes.home);}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>loading=false);}}
 @override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:420),child:Form(key:form,child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.account_balance,size:70),const SizedBox(height:16),Text('Sistema Contábil',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:28),TextFormField(controller:username,validator:Validators.required,decoration:const InputDecoration(labelText:'Usuário (e-mail)'),keyboardType:TextInputType.emailAddress),const SizedBox(height:12),TextFormField(controller:password,validator:Validators.required,decoration:const InputDecoration(labelText:'Senha'),obscureText:true),if(error!=null)Padding(padding:const EdgeInsets.all(12),child:Text(error!,style:const TextStyle(color:Colors.red))),const SizedBox(height:20),FilledButton(onPressed:loading?null:submit,child:loading?const CircularProgressIndicator():const Text('Entrar'))]))))));}
}
